-- Codelist enforcement: every *_id lookup column must hold an active item of the codelist
-- declared in models/*.yaml. Checked on INSERT and when the column changes on UPDATE.

CREATE OR REPLACE FUNCTION ref.assert_code_in_list(p_item uuid, p_code_list text, p_column text) RETURNS void
LANGUAGE plpgsql STABLE AS $$
BEGIN
    IF p_item IS NULL THEN RETURN; END IF;
    PERFORM 1 FROM ref.code_list_item i JOIN ref.code_list l USING (code_list_id)
     WHERE i.code_list_item_id = p_item AND l.code_list_code = p_code_list
       AND i.is_active AND NOT i.is_deleted;
    IF NOT FOUND THEN
        RAISE EXCEPTION '% = % is not an active item of codelist %', p_column, p_item, p_code_list
            USING ERRCODE = 'foreign_key_violation';
    END IF;
END $$;

